### Python

```python
import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    T = int(next(it))
    out_lines = []
    for _ in range(T):
        n = int(next(it))
        k = int(next(it))
        ans = []
        s = n
        while s >= 1:
            if k >= s - 1 and s > 1:
                ans.append(s)
                k -= s - 1
                s -= 1
            else:
                if k == 0:
                    ans.extend(range(1, s + 1))
                else:
                    ans.append(k + 1)
                    ans.extend(range(1, k + 1))
                    ans.extend(range(k + 2, s + 1))
                break
        out_lines.append(' '.join(map(str, ans)))
    sys.stdout.write('\n'.join(out_lines))

if __name__ == "__main__":
    solve()
```

